import{c as i,Q as e,j as l,m as o}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"使用指南","description":"","frontmatter":{"title":"使用指南","outline":"deep"},"headers":[],"relativePath":"guide.md","filePath":"guide.md","lastUpdated":1794895051000}'),t={name:"guide.md"};function r(d,a,h,s,c,n){return e(),l("div",null,[...a[0]||(a[0]=[o(`<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h1><p>本文按实际操作流程介绍 FMCL 的界面与用法。功能清单与边界条件见<a href="/features">功能一览</a>， 配置项含义见<a href="/config">配置说明</a>。</p><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to &quot;首次启动&quot;">​</a></h2><ol><li>启动 FMCL 后先显示启动画面，随后检查运行环境（数据目录、Java、图形后端）。</li><li>首次运行会依次弹出语言选择、使用条款与公告确认；同意后进入主界面。</li><li>主界面左侧是一级导航，按「游戏 / 资源与联机 / 工具与扩展」分组；当前平台不可用的领域（如非 Windows 的已安装基岩版）不会出现。</li><li>顶栏右侧提供搜索、公告、更新检查与设置入口，底部状态栏显示任务进度与操作结果。</li></ol><h2 id="安装游戏版本" tabindex="-1">安装游戏版本 <a class="header-anchor" href="#安装游戏版本" aria-label="Permalink to &quot;安装游戏版本&quot;">​</a></h2><ol><li>左侧导航进入「已安装版本」，点「安装新版本」。</li><li>输入版本 ID（如 <code>1.20.4</code>），或切到「正式版 / 测试版」标签页点选回填（每页 20 条）。</li><li>选择模组加载器：无、Forge、Fabric、NeoForge、Quilt、LiteLoader、LegacyFabric、Cleanroom、OptiFine。 选择加载器时原版 Minecraft 会并行安装，并自动查询该加载器与游戏版本的兼容性。</li><li>点「安装版本」，进度卡显示总进度、当前文件、下载速度与剩余项，可随时取消。</li><li>安装完成后回到版本列表，刷新即可看到新实例。</li></ol><blockquote><p>加载器安装完成后会为该实例启用版本隔离，创建独立的 <code>mods/</code>、<code>config/</code>、<code>saves/</code> 等目录。 国内网络建议在设置中保持「国内镜像」开启，镜像覆盖版本清单、游戏资源、库文件与加载器安装器。</p></blockquote><h2 id="启动游戏" tabindex="-1">启动游戏 <a class="header-anchor" href="#启动游戏" aria-label="Permalink to &quot;启动游戏&quot;">​</a></h2><ol><li>打开左侧导航「游戏」，在「最近使用版本」卡片点「启动游戏」；或进入「已安装版本」选中实例后启动。</li><li>启动前会检查 Java：默认自动扫描系统 Java 并匹配版本；也可在设置 → Java 中指定。</li><li>游戏运行期间按钮变为「强制结束游戏」，点击可结束该进程。</li><li>游戏窗口出现后启动器会按设置决定是否最小化，并关闭 stdout 管道以免拖慢最后加载阶段。</li></ol><p>退出码非 0，或本次启动后新生成崩溃报告 / <code>hs_err</code> 时，会弹出诊断窗：可查看退出码、崩溃报告、游戏日志与 JVM 崩溃日志，导出诊断 ZIP，上传日志到 LogShare.CN，或登录净读账号后做 AI 分析。</p><h2 id="管理已安装版本" tabindex="-1">管理已安装版本 <a class="header-anchor" href="#管理已安装版本" aria-label="Permalink to &quot;管理已安装版本&quot;">​</a></h2><ul><li>版本行提供详情、模组、资源、重命名、删除与打开目录操作。</li><li>重命名会同步修改文件夹名、版本 JSON 文件名与内部 <code>id</code>，已有资源不会丢失。</li><li>删除前二次确认，并清理「最近使用版本」记录。</li><li>校验功能用并发哈希检查实例文件完整性，结果回写到页面。</li></ul><h2 id="资源管理" tabindex="-1">资源管理 <a class="header-anchor" href="#资源管理" aria-label="Permalink to &quot;资源管理&quot;">​</a></h2><p>选中实例后进入「模组」或「资源管理」，可管理四类资源：</p><table tabindex="0"><thead><tr><th>类型</th><th>扩展名</th><th>安装目录</th></tr></thead><tbody><tr><td>模组</td><td><code>.jar</code> <code>.zip</code>，禁用后为 <code>.jar.disabled</code></td><td><code>mods/</code></td></tr><tr><td>资源包</td><td><code>.zip</code></td><td><code>resourcepacks/</code></td></tr><tr><td>地图</td><td><code>.zip</code> 自动解压或文件夹</td><td><code>saves/</code></td></tr><tr><td>光影</td><td><code>.zip</code></td><td><code>shaderpacks/</code></td></tr></tbody></table><ul><li>安装方式：拖拽文件到窗口，或点「选择文件安装」。</li><li>模组卡片读取 jar 内元数据（图标、名称、作者、modid、版本）；资源包与光影从 zip 提取预览图。</li><li>支持类型化搜索、分页、启用与禁用、删除、打开目录，以及把模组列表复制到剪贴板。</li><li>「检查更新」同时查询 Modrinth 与 CurseForge，可勾选后批量更新，失败项保留已完成文件。</li></ul><blockquote><p>原版实例只显示资源包与地图；安装加载器后才出现模组与光影，与版本隔离规则一致。</p></blockquote><h2 id="在线资源浏览" tabindex="-1">在线资源浏览 <a class="header-anchor" href="#在线资源浏览" aria-label="Permalink to &quot;在线资源浏览&quot;">​</a></h2><p>左侧导航进入「资源浏览」：</p><ol><li>进入即加载热门内容；可切换模组、资源包、光影类型。</li><li>用关键词、游戏版本与加载器筛选；游戏版本与加载器默认按当前实例自动填好。</li><li>卡片刻显示名称、作者、下载量与简介；点开详情可选择具体版本、预览依赖并安装到指定实例。</li><li>安装时递归处理 <code>required</code> 依赖；找不到兼容版本时跳过并提示。</li><li>未配置 <code>CURSEFORGE_API_KEY</code> 时自动只查 Modrinth；登录净读账号后可使用 AI 搜索扩展关键词。</li></ol><h2 id="安装整合包" tabindex="-1">安装整合包 <a class="header-anchor" href="#安装整合包" aria-label="Permalink to &quot;安装整合包&quot;">​</a></h2><p>在「已安装版本」→「安装新版本」→「安装整合包」中：</p><ol><li>选择来源：本地 <code>.mrpack</code> / MultiMC / CurseForge / HMCL / MCBBS / 通用压缩包，或点「从在线浏览下载」。</li><li>程序解析元数据、可选组件与组件清单；<code>.mrpack</code> 的可选文件可勾选。</li><li>可自定义实例名（默认整合包名，冲突或非法名称会禁用开始按钮）。</li><li>点「开始安装」，等待并行阶段与加载器安装完成。</li><li>安装完成后自动刷新版本列表，可直接启动，也可进入资源管理。</li></ol><blockquote><p>自定义实例名会生成该实例自己的版本 JSON，版本列表、启动与资源管理都按这个实例识别； 这也是自定义名称的整合包实例能被正确识别的原因。</p></blockquote><h2 id="服务器" tabindex="-1">服务器 <a class="header-anchor" href="#服务器" aria-label="Permalink to &quot;服务器&quot;">​</a></h2><h3 id="安装与启动" tabindex="-1">安装与启动 <a class="header-anchor" href="#安装与启动" aria-label="Permalink to &quot;安装与启动&quot;">​</a></h3><ol><li>左侧导航进入「服务器」，点「安装服务器」。</li><li>输入版本 ID，或从正式版列表点选（每页 10 条）。</li><li>安装完成后在服务器列表点启动；可同时运行多台服务器。</li><li>首启会生成基础 <code>server.properties</code> 并同意 EULA；默认使用离线模式。</li><li>每台服务器可单独设置最大内存（1G 到 16G），保存在该服务器目录的 <code>.fmcl_server.json</code>。</li></ol><p>端口被占用时启动器会自动顺延到空闲端口并回写配置，并在列表与详情页提示实际端口。</p><h3 id="控制台" tabindex="-1">控制台 <a class="header-anchor" href="#控制台" aria-label="Permalink to &quot;控制台&quot;">​</a></h3><p>服务器详情页的控制台显示运行状态、在线玩家与每 2 秒一次的内存采样；日志自动滚底，最多保留 5000 行。 底部命令框支持回车或按钮发送命令，也可清屏与导出日志。</p><h3 id="配置编辑器" tabindex="-1">配置编辑器 <a class="header-anchor" href="#配置编辑器" aria-label="Permalink to &quot;配置编辑器&quot;">​</a></h3><p>点服务器行或详情页的配置按钮，按 7 类编辑 <code>server.properties</code>：</p><ul><li>支持按名称、键名（如 <code>motd</code>）或说明搜索，每个配置项显示中文名称、原始键名与一句话说明。</li><li>数字项显示取值范围，越界时标红并弹窗提示。</li><li>保存只更新改动过的键，保留注释与未知键；可单项或整类恢复默认。</li><li>「原始文件」分类可直接编辑文本；页面对未保存修改启用离开守卫。</li></ul><h3 id="整合包开服" tabindex="-1">整合包开服 <a class="header-anchor" href="#整合包开服" aria-label="Permalink to &quot;整合包开服&quot;">​</a></h3><p>在「服务器」→「安装服务器」旁可选用整合包开服，只接受 <code>.mrpack</code>。安装时会自动检测 Forge / Fabric / NeoForge / Quilt 服务端加载器，Fabric 缺少 Fabric API 时自动补装；用途不明的模组会在安装后集中列出，可逐项禁用。</p><h2 id="陶瓦联机" tabindex="-1">陶瓦联机 <a class="header-anchor" href="#陶瓦联机" aria-label="Permalink to &quot;陶瓦联机&quot;">​</a></h2><p>仅 Windows 可用。首次进入会检测并引导安装 EasyTier（多镜像测速，失败自动回退）。</p><p>创建大厅：</p><ol><li>输入本地 Minecraft 端口（默认 25565）与显示名称。</li><li>点「创建大厅」，约 5 秒后就绪。</li><li>把生成的陶瓦编号（<code>U/</code> 前缀 21 位）发给好友。</li></ol><p>加入大厅：</p><ol><li>输入编号与显示名称，点「加入大厅」。</li><li>建立连接后，在 Minecraft 多人游戏中连接 <code>localhost</code> 即可。</li><li>成员列表主机优先显示，底部实时显示与主机的延迟。</li></ol><p>「扫描」按钮可发现同一局域网中的共享世界，只展示结果，不会自动进入。</p><h2 id="存档备份" tabindex="-1">存档备份 <a class="header-anchor" href="#存档备份" aria-label="Permalink to &quot;存档备份&quot;">​</a></h2><p>左侧导航进入「存档」：</p><ol><li>页面自动扫描全局 <code>saves/</code> 与各实例隔离目录，刷新时重扫。</li><li>选中存档后可点「备份」，可填写备注，压缩进度真实显示。</li><li>备份列表显示时间、大小、游戏版本与备注，支持恢复、校验、导出 ZIP 与删除。</li><li>恢复前校验 ZIP 完整性，默认把当前存档重命名为 <code>_bak_时间戳</code> 保留。</li><li>页面底部可开启「启动游戏前备份」与「游戏退出后备份」，开关即时写入配置。</li></ol><p>设置中可改备份路径、压缩等级（1 / 3 / 6 / 9）、每存档保留数量（5 / 10 / 20 / 30 / 50 / 不限）与恢复时旧存档处理方式。</p><h2 id="音乐" tabindex="-1">音乐 <a class="header-anchor" href="#音乐" aria-label="Permalink to &quot;音乐&quot;">​</a></h2><p>左侧导航进入「音乐」，「发现」首页展示每日推荐、推荐歌单、排行榜与最新音乐。</p><ul><li><strong>本地音乐</strong>：选择文件夹后递归扫描 MP3 / FLAC / OGG / WAV / M4A / AAC，读取标签与内嵌封面，可「播放全部」。</li><li><strong>在线搜索</strong>：同时查询网易云、QQ、酷我、酷狗、咪咕，B 站作为跨源兜底；自动选择可用最高音质。</li><li><strong>歌单</strong>：全部歌曲、我喜欢的音乐、最近播放、自建歌单与网易云歌单；支持排序与「播放全部」。</li><li><strong>歌词</strong>：LRC、翻译与罗马音；桌面歌词三行滚动，可锁定与解锁拖拽、调透明度。</li><li><strong>热键</strong>：<code>Ctrl+Shift+Space</code> 播放与暂停、<code>Ctrl+Shift+Left/Right</code> 切歌、<code>Ctrl+Shift+Down</code> 停止、 <code>Ctrl+Shift+Up/PageDown</code> 音量、<code>Ctrl+Shift+Alt+M</code> 静音。</li></ul><p>播放失败时会自动跨源搜索同曲，并用时长校验排除翻唱与伴奏；Windows 上同时支持系统媒体控制 SMTC。</p><h2 id="工具箱" tabindex="-1">工具箱 <a class="header-anchor" href="#工具箱" aria-label="Permalink to &quot;工具箱&quot;">​</a></h2><p>左侧导航进入「工具」。九个小工具：清理游戏垃圾、端口检测、Hash 计算、坐标转换、今日人品、冷知识、 知识问答、多线程下载、相关网站。</p><p>性能监控：按 <code>Ctrl+Shift+M</code> 或点顶栏监视器按钮打开悬浮窗，显示 CPU、内存与 GPU 数据，可拖拽并记住位置。</p><h2 id="成就与签到" tabindex="-1">成就与签到 <a class="header-anchor" href="#成就与签到" aria-label="Permalink to &quot;成就与签到&quot;">​</a></h2><p>左侧导航进入「成就总览」，显示 47 项成就的总进度与 9 个分类，卡片带进度与阶段。 解锁成就会在右下角提示；首页显示连续签到天数。登录净读账号后可在「云端」分类做云存档同步。</p><h2 id="agent-与语音" tabindex="-1">AGENT 与语音 <a class="header-anchor" href="#agent-与语音" aria-label="Permalink to &quot;AGENT 与语音&quot;">​</a></h2><p>左侧导航进入「AGENT」：</p><ol><li>左侧会话列表可新建、切换、重命名、删除会话，历史自动保存。</li><li>在输入框描述需求，例如「帮我安装 1.20.4 的 Fabric 版本」。</li><li>工具调用会显示参数与结果；高危命令、文件修改与提问都需要二次确认，文件写改删会先预览 diff。</li><li>右上可选择提供商与模型；设置 → AI 中可配置 API Key、端点、思考强度和工具权限。</li></ol><p>顶栏快速输入框按 Enter 会直接跳到 AGENT 并发送。输入框旁的语音按钮使用 SenseVoice 离线模型做语音输入， 首次使用会自动下载模型。</p><p>命令行同样可用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;帮我安装最新版&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span></span></code></pre></div><h2 id="基岩版" tabindex="-1">基岩版 <a class="header-anchor" href="#基岩版" aria-label="Permalink to &quot;基岩版&quot;">​</a></h2><p>仅 Windows 10 19041 及以上。左侧导航进入「已安装基岩版」：</p><ol><li>在版本库中搜索或筛选 UWP / GDK，每页 20 条。</li><li>首次安装需要同意 MCAPPX 条款；GDK 会检测 .NET 10 SDK 并提供下载引导。</li><li>安装使用真实进度与断点续传，完成后可直接启动。</li><li>已安装卡片支持启动、删除、详情与打开版本目录。</li></ol><h2 id="设置与账号" tabindex="-1">设置与账号 <a class="header-anchor" href="#设置与账号" aria-label="Permalink to &quot;设置与账号&quot;">​</a></h2><h3 id="设置分区" tabindex="-1">设置分区 <a class="header-anchor" href="#设置分区" aria-label="Permalink to &quot;设置分区&quot;">​</a></h3><p>左侧导航进入「设置」，共 9 个分区：启动器、Java、主题、音乐账号、日志、关于、账号、AI、插件。 改动先进入草稿，可预览主题与语言，点保存才写盘；带未保存修改离开会提示。</p><h3 id="账号" tabindex="-1">账号 <a class="header-anchor" href="#账号" aria-label="Permalink to &quot;账号&quot;">​</a></h3><ul><li><strong>微软正版</strong>：默认使用 PKCE OAuth，另提供设备代码登录。</li><li><strong>离线</strong>：本地生成 UUID，无需联网。</li><li><strong>Yggdrasil</strong>：连接皮肤站等第三方验证服务器时自动注入 <code>authlib-injector</code>。</li></ul><p>账号可添加、删除、切换与设为当前，也支持导入导出加密的 <code>.fmcl_accounts</code> 文件。角色名由当前账号决定。</p><h3 id="主题与语言" tabindex="-1">主题与语言 <a class="header-anchor" href="#主题与语言" aria-label="Permalink to &quot;主题与语言&quot;">​</a></h3><p>主题分区提供 5 套预设、导入 <code>.json</code> 主题、自定义 <code>#RRGGBB</code> 强调色与版本动态主题。 语言支持简体中文、English、繁體中文、日本語，切换即时生效。</p><h2 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h2><p>在「设置」→「插件」打开插件管理器：</p><ol><li>「从文件安装」选择 <code>.fmpl</code> 插件包，或在「插件市场」中浏览并一键安装。</li><li>列表显示名称、版本、作者与状态，可启用、禁用、卸载与查看权限。</li><li>启用与禁用均热加载，不需要重启；高风险权限每次使用都会弹窗确认。</li><li>提供 QML 页面的插件会出现在侧栏底部的「插件」分组。</li></ol><p>插件开发见<a href="/plugin">插件开发指南</a>。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><p>Windows 上启动器会在启动时检查更新（可在设置中关闭）。发现新版本时会显示版本号与更新日志， 也可在「设置 → 关于」中手动检查、下载并启动安装包。</p><p>Linux 与 macOS 不提供自动安装：Linux 可用一键安装脚本或重新下载 tarball，macOS 请从源码更新。</p>`,79)])])}const b=i(t,[["render",r]]);export{u as __pageData,b as default};
